/* ---------- engine ---------- */
(function () {
  const store = { get(k, d) { try { return JSON.parse(localStorage.getItem("et:" + k)) ?? d; } catch { return d; } }, set(k, v) { try { localStorage.setItem("et:" + k, JSON.stringify(v)); } catch {} } };
  const fromUrl = new URLSearchParams(location.search).get("lang");
  ET.lang = (fromUrl && ET.LANGS[fromUrl]) ? fromUrl : store.get("lang", (navigator.language || "en").slice(0, 2));
  if (!ET.LANGS[ET.lang]) ET.lang = "en";
  const dict = () => ET.I18N[ET.lang] || {};
  ET.t = (s) => dict()[s] || s;
  const SKIP = { SCRIPT: 1, STYLE: 1, NOSCRIPT: 1, SVG: 1, CODE: 1, PRE: 1 };
  const ATTRS = ["placeholder", "title", "aria-label"];
  const rules = [
    [/^\((\S+) reviews\)$/, (m, d) => `(${m[1]} ${d["reviews"] || "reviews"})`],
    [/^(\S+) verified reviews$/, (m, d) => `${m[1]} ${d["verified reviews"] || "verified reviews"}`],
    [/^(\d+) tours$/, (m, d) => `${m[1]} ${d["tours"] || "tours"}`]
  ];
  function translateText(node) {
    const d = dict();
    const en = node.__en !== undefined ? node.__en : node.nodeValue;
    if (node.__en === undefined) node.__en = en;
    const key = en.trim();
    if (!key) return;
    let out = null;
    if (ET.lang !== "en") {
      if (d[key]) out = d[key];
      else for (const [re, fn] of rules) { const m = key.match(re); if (m) { out = fn(m, d); break; } }
    }
    const val = out ? en.replace(key, out) : en;
    if (node.nodeValue !== val) node.nodeValue = val;
  }
  function walk(root) {
    if (!root) return;
    if (root.nodeType === 3) { translateText(root); return; }
    if (root.nodeType !== 1 || SKIP[root.tagName]) return;
    for (const a of ATTRS) {
      if (root.hasAttribute(a)) {
        const en = root.__enAttr?.[a] ?? root.getAttribute(a);
        root.__enAttr = root.__enAttr || {}; root.__enAttr[a] = en;
        const v = ET.lang === "en" ? en : (dict()[en] || en);
        if (root.getAttribute(a) !== v) root.setAttribute(a, v);
      }
    }
    for (const c of root.childNodes) walk(c);
  }
  let fontLoaded = {};
  ET.applyLang = function (lang, persist) {
    if (lang && ET.LANGS[lang]) ET.lang = lang;
    if (persist !== false) store.set("lang", ET.lang);
    const L = ET.LANGS[ET.lang];
    document.documentElement.lang = ET.lang;
    document.documentElement.dir = L.dir;
    if (L.font && !fontLoaded[ET.lang]) { fontLoaded[ET.lang] = 1; const l = document.createElement("link"); l.rel = "stylesheet"; l.href = "https://fonts.googleapis.com/css2?family=" + L.font + "&display=swap"; document.head.appendChild(l); }
    document.documentElement.style.setProperty("--font-lang", L.family || "inherit");
    document.documentElement.classList.toggle("lang-alt", ET.lang !== "en");
    walk(document.body);
    const t = document.querySelector("title"); if (t) walk(t);
    document.querySelectorAll("#langSel").forEach((s) => (s.value = ET.lang));
    document.dispatchEvent(new CustomEvent("et:lang", { detail: ET.lang }));
  };
  // translate nodes added later (cards, modals, planner, toasts)
  const mo = new MutationObserver((ms) => { if (ET.lang === "en") return; for (const m of ms) { if (m.type === "characterData") { if (m.target.__en === undefined) translateText(m.target); } else m.addedNodes.forEach((n) => walk(n)); } });
  document.addEventListener("DOMContentLoaded", () => {
    ET.applyLang(ET.lang, false);
    mo.observe(document.body, { childList: true, subtree: true, characterData: true });
  });
})();
